// Aurora ribbons drifting across a dark night sky.
uniform float uSpeed;  // @param 0.15 0 1
uniform float uCount;  // @param 4 1 8
uniform vec3  uGlow;   // @param #3DFFB0

void main() {
  float aspect = iResolution.x / iResolution.y;
  vec2 p = vec2((uv.x - 0.5) * aspect, uv.y);
  float t = iTime * uSpeed;

  // Dark sky gradient
  vec3 col = mix(vec3(0.012, 0.02, 0.05), vec3(0.002, 0.004, 0.015), uv.y);

  // Twinkling stars
  vec2 cell = floor(vec2(uv.x * aspect, uv.y) * 220.0);
  float s = hash(cell);
  float star = step(0.996, s) * (0.55 + 0.45 * sin(iTime * 1.7 + s * 90.0));
  col += vec3(0.8, 0.85, 1.0) * star * 0.5 * smoothstep(0.05, 0.5, uv.y);

  // Aurora ribbons
  vec3 topTint = mix(uGlow, vec3(0.55, 0.2, 0.9), 0.6);
  vec3 aur = vec3(0.0);
  for (int i = 0; i < 8; i++) {
    float fi = float(i);
    float on = clamp(uCount - fi, 0.0, 1.0); // fractional count fades ribbons in smoothly
    if (on <= 0.0) break;
    float seed = hash1(fi + 1.3);
    float dir = mod(fi, 2.0) < 1.0 ? 1.0 : -1.0;
    float drift = t * (0.6 + 0.5 * seed) * dir;
    float x = p.x;

    float base = 0.3 + 0.45 * hash1(fi * 3.7 + 0.2);
    float y = base
            + 0.12 * sin(x * (1.2 + seed) + drift * 1.3 + seed * 6.28)
            + 0.18 * (fbm(vec2(x * 0.8 + drift, fi * 4.1 + t * 0.3)) - 0.5);

    float d = p.y - y;
    float below = exp(-max(-d, 0.0) * 60.0);            // crisp lower edge
    float above = exp(-max(d, 0.0) * (5.0 + 4.0 * seed)); // long upward curtain
    float curtain = below * above;

    float rays = 0.55 + 0.45 * noise(vec2(x * 28.0 + drift * 3.0, fi * 7.0));
    rays *= 0.7 + 0.3 * noise(vec2(x * 90.0, t + fi));
    float fadeX = 0.35 + 0.65 * fbm(vec2(x * 1.5 - drift * 0.7, fi * 2.3));

    float a = curtain * rays * fadeX * on;
    vec3 c = mix(uGlow, topTint, smoothstep(0.0, 0.25, d));
    aur += c * a * 0.55;
  }

  // Soft glow tonemap so overlapping ribbons bloom instead of clipping
  col += 1.0 - exp(-aur * 1.6);
  fragColor = vec4(col, 1.0);
}
